function [255:0] rom_w2_0(input dummy); rom_w2_0 = 256'h67707f7f8181f5087f037f7feb7f738181817d8181817f7fccadc17f7f8181d3; endfunction
function [255:0] rom_w2_1(input dummy); rom_w2_1 = 256'h7f81ed7f810edafe811ea17fcd7f7f7f1e8181817fa281813a7f7fc381817f81; endfunction

    assign w_row = rom_row(row_sel);
    assign w2_0  = rom_w2_0(1'b0);
    assign w2_1  = rom_w2_1(1'b0);
    assign wr_ready = 1'b0;
  end else begin : g_scmem
    // The register file is clocked only while it is being written (wr_clk, see above): the 50 k weight flip-flops
    // are off the core clock tree, receive no clock edge during decoding, and their outputs are static whenever
    // the core is busy (writes are only accepted in IDLE) - the SDC declares the wr_clk domain a false path.
    assign wr_ready = wr_en_q;
    reg [WB-1:0] wmem  [0:96];
    reg [7:0]    w2m0  [0:H-1];
    reg [7:0]    w2m1  [0:H-1];
    wire [6:0] wr_row  = wr_addr[10:4];
    wire [3:0] wr_word = wr_addr[3:0];
    wire       wr_w2   = (wr_addr >= 11'd1600);
    wire [5:0] wr_j    = wr_addr[5:0];   // 1600 = 25*64 -> low 6 bits of (addr-1600) == addr[5:0]
    always @(posedge wr_clk) begin
      if (wr_en) begin
        if (wr_w2) begin
          w2m0[wr_j] <= wr_data[7:0];
          w2m1[wr_j] <= wr_data[15:8];
        end else if (wr_row <= 7'd96) begin
          wmem[wr_row][32*wr_word +: 32] <= wr_data;
        end
      end
    end
    // one-hot AND-OR read multiplexer driven by the registered select sel_r
    reg [WB-1:0] w_row_oh;
    integer ri;
    always @(*) begin
      w_row_oh = {WB{1'b0}};
      for (ri = 0; ri < 97; ri = ri + 1)
        w_row_oh = w_row_oh | ({WB{sel_r[ri]}} & wmem[ri]);
    end
    assign w_row = w_row_oh;
    genvar gj;
    for (gj = 0; gj < H; gj = gj + 1) begin : g_w2
      assign w2_0[8*gj +: 8] = w2m0[gj];
      assign w2_1[8*gj +: 8] = w2m1[gj];
    end
  end endgenerate
`endif

  // ------------------------------------------------------------------ datapath
  function signed [V_BITS-1:0] sat_add20(input signed [V_BITS-1:0] a, input signed [7:0] w);
    reg signed [V_BITS:0] s;
    begin
      s = {a[V_BITS-1], a} + {{(V_BITS-7){w[7]}}, w};
      if (s > V_MAX)      sat_add20 = V_MAX[V_BITS-1:0];
      else if (s < V_MIN) sat_add20 = V_MIN[V_BITS-1:0];
      else                sat_add20 = s[V_BITS-1:0];
    end
  endfunction
  function signed [O_BITS-1:0] sat_add24w(input signed [O_BITS-1:0] a, input signed [7:0] w);   // O_BITS >= 9
    reg signed [O_BITS:0] s;
    begin
      s = {a[O_BITS-1], a} + {{(O_BITS-7){w[7]}}, w};
      if (s > O_MAX)      sat_add24w = O_MAX[O_BITS-1:0];
      else if (s < O_MIN) sat_add24w = O_MIN[O_BITS-1:0];
      else                sat_add24w = s[O_BITS-1:0];
    end
  endfunction

  // leak / threshold for all neurons (used in S_SCAN)
  wire signed [V_BITS-1:0] vl  [0:H-1];
  wire               spk [0:H-1];
  genvar gk;
  generate for (gk = 0; gk < H; gk = gk + 1) begin : g_lif
    assign vl[gk]  = v[gk] - (v[gk] >>> K1);
    assign spk[gk] = (vl[gk] >= THETA);
  end endgenerate

  // output accumulation: one spiking neuron per cycle (about one per bin), lowest index first.
  // The first-set finder is a balanced 6-level tree (a linear priority chain over 64 bits is too slow at the slow corner).
  function [6:0] ffs64(input [63:0] s);   // {found, index}; packed vectors only (Yosys has no arrays in functions)
    reg [63:0]  a;
    reg [383:0] ix;                        // 64 x 6-bit indices
    integer     l, i, n;
    begin
      a = s;
      for (i = 0; i < 64; i = i + 1) ix[6*i +: 6] = i[5:0];
      for (l = 0; l < 6; l = l + 1)            // constant loop bounds for synthesis; level l has 64 >> (l+1) pairs
        for (i = 0; i < 32; i = i + 1)
          if (i < (64 >> (l + 1))) begin
            ix[6*i +: 6] = a[2*i] ? ix[6*(2*i) +: 6] : ix[6*(2*i+1) +: 6];
            a[i]         = a[2*i] | a[2*i+1];
          end
      n = 0;
      ffs64 = {a[0], ix[5:0]};
    end
  endfunction
  // H > 64 (round-5 energy-accuracy grid, H = 128): the same tree one level deeper; the extra level is constant-folded away below 128
  function [7:0] ffs128(input [127:0] s);  // {found, index[6:0]}
    reg [127:0] a;
    reg [895:0] ix;                        // 128 x 7-bit indices
    integer     l, i;
    begin
      a = s;
      for (i = 0; i < 128; i = i + 1) ix[7*i +: 7] = i[6:0];
      for (l = 0; l < 7; l = l + 1)
        for (i = 0; i < 64; i = i + 1)
          if (i < (128 >> (l + 1))) begin
            ix[7*i +: 7] = a[2*i] ? ix[7*(2*i) +: 7] : ix[7*(2*i+1) +: 7];
            a[i]         = a[2*i] | a[2*i+1];
          end
      ffs128 = {a[0], ix[6:0]};
    end
  endfunction
  wire        any_spk;
  wire [6:0]  j_sel;
  generate if (H > 64) begin : g_ffs_wide
    wire [127:0] s_pad = {{(128-H){1'b0}}, s_r};
    wire [7:0]   ffs   = ffs128(s_pad);
    assign any_spk = ffs[7];
    assign j_sel   = ffs[6:0];
  end else begin : g_ffs
    wire [63:0] s_pad = {{(64-H){1'b0}}, s_r};
    wire [6:0]  ffs   = ffs64(s_pad);
    assign any_spk = ffs[6];
    assign j_sel   = {1'b0, ffs[5:0]};
  end endgenerate
  wire signed [7:0] w2sel_0 = w2_0[8*j_sel +: 8];
  wire signed [7:0] w2sel_1 = w2_1[8*j_sel +: 8];
`ifdef W2_PIPE
  reg               p1_valid, p2_valid;      // stage 1: index of the spiking neuron; stage 2: its W2 bytes
  reg  [6:0]        p1_j;
  reg  signed [7:0] p2_w0, p2_w1;
  wire              w2_busy = p1_valid | p2_valid;
`endif

  // ---- weight-row pipeline registers (w_clk domain)
  always @(posedge w_clk) begin
    if (reset) begin
      w_row_r <= {WB{1'b0}}; sel_r <= 97'd0;
    end else if (HARDWIRED) begin
      if (f_valid) w_row_r <= w_row;
    end else begin
      if (f_valid) sel_r <= (97'd1 << f_row);
      if (g_valid) w_row_r <= w_row;
    end
  end

  // ---- membrane bank (v_clk domain)
  integer n;
  always @(posedge v_clk) begin
    if (reset) begin
      for (n = 0; n < H; n = n + 1) v[n] <= {V_BITS{1'b0}};
    end else begin
`ifdef GATE_DP
      // v_clk pulses only in an A-stage cycle or in the tick scan (never both), so the bank is written unconditionally
      // and needs no hold multiplexers
      for (n = 0; n < H; n = n + 1)
        v[n] <= (state == S_SCAN) ? (spk[n] ? {V_BITS{1'b0}} : vl[n])
                                  : sat_add20(v[n], a_gate ? w_row_r[8*n +: 8] : 8'sd0);
`else
      if (a_valid)
        for (n = 0; n < H; n = n + 1)
          v[n] <= sat_add20(v[n], a_gate ? w_row_r[8*n +: 8] : 8'sd0);
      if (state == S_SCAN)
        for (n = 0; n < H; n = n + 1)
          v[n] <= spk[n] ? {V_BITS{1'b0}} : vl[n];
`endif
    end
  end

  // ---- control and outputs (core_clk domain)
  integer m;
  always @(posedge core_clk) begin
    if (reset) begin
      state <= S_IDLE; f_row <= 7'd0; f_gate <= 1'b0; a_gate <= 1'b0; f_valid <= 1'b0; a_valid <= 1'b0;
      g_valid <= 1'b0; g_gate <= 1'b0;
      row_cnt <= 7'd0; x <= 96'd0; s_r <= {H{1'b0}};
      out_valid <= 1'b0; o0 <= {O_BITS{1'b0}}; o1 <= {O_BITS{1'b0}};
`ifdef W2_PIPE
      p1_valid <= 1'b0; p2_valid <= 1'b0; p1_j <= 7'd0; p2_w0 <= 8'sd0; p2_w1 <= 8'sd0;
`endif
    end else begin
      out_valid <= 1'b0;
      // ---- row pipeline valids, independent of the state machine (data registers: see the w_clk / v_clk blocks)
      f_valid <= 1'b0;
      if (HARDWIRED) begin
        a_valid <= f_valid;
        if (f_valid) a_gate <= f_gate;
      end else begin
        g_valid <= f_valid;
        if (f_valid) g_gate <= f_gate;
        a_valid <= g_valid;
        if (g_valid) a_gate <= g_gate;
      end
`ifdef W2_PIPE
      // ---- output-accumulation pipeline (stage 1 index -> stage 2 W2 bytes -> add), fed by S_OUT one spike per cycle
      p1_valid <= (state == S_OUT) & any_spk;
      p2_valid <= p1_valid;
      if (p1_valid) begin p2_w0 <= w2_0[8*p1_j +: 8]; p2_w1 <= w2_1[8*p1_j +: 8]; end
      if (p2_valid) begin o0 <= sat_add24w(o0, p2_w0); o1 <= sat_add24w(o1, p2_w1); end
`endif
      // ---- control
      case (state)
        S_IDLE: begin
          if (wr_en) begin
            // weight write handled by the weight-memory logic
          end else if (ev_valid) begin
            if (DENSE && mode_dense) x[ev_ch] <= 1'b1;
            else begin f_row <= ev_ch; f_gate <= 1'b1; f_valid <= 1'b1; end
          end else if (tick && !f_valid && !g_valid && !a_valid) begin
            if (DENSE && mode_dense) begin f_row <= 7'd0; f_gate <= x[0]; f_valid <= 1'b1; row_cnt <= 7'd1; state <= S_DENSE; end
            else                     begin f_row <= 7'd96; f_gate <= 1'b1; f_valid <= 1'b1; state <= S_TICK; end
          end
        end
        S_DENSE: begin                   // issue rows 1..95 (gated by the input bit) and the bias row 96
          f_row <= row_cnt; f_gate <= (row_cnt == 7'd96) ? 1'b1 : x[row_cnt]; f_valid <= 1'b1;
          row_cnt <= row_cnt + 7'd1;
          if (row_cnt == 7'd96) state <= S_TICK;
        end
        S_TICK: begin                    // wait until the bias row has been added (pipeline drained)
          if (a_valid && !f_valid && !g_valid) state <= S_SCAN;
        end
        S_SCAN: begin                    // all neurons in parallel (membranes: v_clk block); outputs leak
          for (m = 0; m < H; m = m + 1) s_r[m] <= spk[m];
          o0 <= o0 - (o0 >>> K2);
          o1 <= o1 - (o1 >>> K2);
          state <= S_OUT;
        end
        S_OUT: begin                     // accumulate W2 of the spiking neurons, one per cycle
`ifdef W2_PIPE
          if (any_spk) begin p1_j <= {1'b0, ffs[5:0]}; s_r[j_sel] <= 1'b0; end
          else if (!w2_busy) begin out_valid <= 1'b1; x <= 96'd0; state <= S_IDLE; end
`else
          if (any_spk) begin
            o0 <= sat_add24w(o0, w2sel_0);
            o1 <= sat_add24w(o1, w2sel_1);
            s_r[j_sel] <= 1'b0;
          end else begin
            out_valid <= 1'b1; x <= 96'd0; state <= S_IDLE;
          end
`endif
        end
        default: state <= S_IDLE;
      endcase
    end
  end
endmodule
